#!/usr/bin/env bash
# Harbor's whole cycle on a project generated by Keelokit, with Keelokit's real verify and hooks.
#
#   scripts/test-with-keelokit.sh [REF]      default v0.16.0 (phase 6's ledger); v0.12.0 is the first that works;
#                                            `main` (any branch or sha) runs Keelokit's unreleased template
#
# KEELOKIT_SRC: the template (default gh:leosimini/keelokit; a local clone works). KEEP=1 keeps the
# work folder. Needs git, uv, pnpm and Node 22; no Docker: the project is web-only, so no step needs a
# database. What it proves, each with an assertion:
#   - a vessel verified the way build-story does under the convoy policy (`pnpm verify`) runs its verify
#     once: the push of its branch reuses Keelokit's seal, and Harbor's seal reuses the same run;
#   - a logbook write from a checkout with unverified work runs no verify (Keelokit's pre-push lets the
#     logbook through: every file under harbor/, every seal backed by a green run here);
#   - another clone (another machine) accepts that kind of seal through [verify] shared_seals;
#   - assemble, the ok, the convoy's one verify and the sail end with main at the convoy's head,
#     pushed through Keelokit's own pre-push hook; the verify that hook runs when assemble pushes
#     convoy/<n> is the convoy's verify, so `convoy verify` runs nothing;
#   - with Keelokit's ledger (`ledger.py --json` answers schema 1, 0.15.0 on): each vessel's merge into convoy/<n>
#     ends with `Convoy: <n>` and reaches main; `convoy add` takes the vessel's story from `ledger.py attribution`,
#     or, with a Keelokit that doesn't answer it yet (0.16.0), says so and reads the Story: trailers;
#   - taking a story is a lock in the logbook (HRB-2): two machines take one story, the second gets STORY_TAKEN
#     with the holder; once the story is on main, Keelokit's real ledger makes a take STORY_ON_TRUNK (0.16.0 has
#     no `show <ID> --json`: the state comes from `ledger.py --json`).
#   - the ledger in the round and the ok (HRB-3): the ok asks the real `ledger.py --json` and `check --json` and
#     records `ledger = "checked"`; the round reads `check --json` (never "not available" with the ledger).
#   - with Keelokit's LEDGER-013 (detected by feature: `ledger.py attribution` answers; required when REF is main):
#     `convoy add` takes each story from the real `attribution` and refuses a really unattributed commit with
#     NO_STORY; a vessel prompt's `ledger.py take <ID>` from a second session gets STORY_TAKEN, and the session it
#     hands over (CLAUDE_CODE_SESSION_ID as HARBOR_SESSION) is the worker that holds the story; `show <ID> --json`
#     says on-trunk and Harbor's take says STORY_ON_TRUNK; the ok runs `check --rules-ref <main tip>`.
#   - a convoy that adds its own correction row for an integrator's unattributed commit is refused by the ok
#     (LEDGER_DIFF); with --rules-ref, main's ledger on the convoy as landed names that commit UNATTRIBUTED (the
#     row is the convoy's, not main's), which Keelokit 0.16.0, reading the convoy's corrections, can't.
# In a container whose Playwright browsers don't match the template's, point PLAYWRIGHT_BROWSERS_PATH
# at a folder with the right version name linked to the browser you have.
set -euo pipefail

tag=${1:-v0.16.0}
src=${KEELOKIT_SRC:-gh:leosimini/keelokit}
harbor=$(cd "$(dirname "$0")/.." && pwd)/lib/harbor.py
work=$(mktemp -d)
[ "${KEEP:-}" = 1 ] && echo "work folder: $work" || trap 'rm -rf "$work"' EXIT
export GIT_AUTHOR_NAME=harbor-test GIT_AUTHOR_EMAIL=harbor-test@example.com
export GIT_COMMITTER_NAME=harbor-test GIT_COMMITTER_EMAIL=harbor-test@example.com
export KEELOKIT_ALLOW_MISSING="${KEELOKIT_ALLOW_MISSING:-gitleaks semgrep}"
step() { printf '\n\033[1m▶ %s\033[0m\n' "$*"; }
fail() { printf '\n\033[31m✖ %s\033[0m\n' "$*" >&2; exit 1; }
H() { local s=$1; shift; python3 "$harbor" --session "$s" "$@"; }
seal_of() { git -C "$1" show "origin/harbor/log:harbor/seals/$2.toml"; }
runs_of() { grep -c "\"head\": \"$2\"" "$1/.git/keelokit-verify.history" 2>/dev/null || true; }
history_lines() { wc -l <"$1/.git/keelokit-verify.history" 2>/dev/null || echo 0; }

step "Generate a web-only project from Keelokit $tag"
seed=$work/seed
mkdir -p "$seed/docs/context"
git -C "$seed" init -q -b main
for f in product domain constraints environments; do printf '# %s\n\nStub.\n' "$f" >"$seed/docs/context/$f.md"; done
printf '# Gaps\n\n| Id | File | Missing | Owner | Question | Blocking |\n|---|---|---|---|---|---|\n' >"$seed/docs/context/gaps.md"
uvx copier==9.18.2 copy --quiet --vcs-ref "$tag" --defaults --data project_name=Demo --data 'apps=["web"]' \
  --data postgis=false "$src" "$seed"
cat >>"$seed/.keelokit/state.toml" <<'TOML'

[landing]
policy = "convoy"

[verify]
shared_seals = "origin/harbor/log:harbor/seals/{head}.toml"

[harbor]
ci_check = ""
TOML
printf '.keelokit/local.toml\n' >>"$seed/.gitignore"
# The two stories the vessels build. From Keelokit 0.16.0 its commit-msg hook refuses a commit with no Story:,
# Part-of: or No-story:, or naming a story no story file of the trunk has, so every commit here carries one.
mkdir -p "$seed/backlog/stories"
for id in DEMO-001 DEMO-002 DEMO-003; do
  cat >"$seed/backlog/stories/$id-harbor-demo.md" <<STORY
+++
id = "$id"
epic = "DEMO"
title = "Harbor demo $id"
wave = 1
depends_on = []
touches = []
dimensions = ["logic"]
+++
## Context
A vessel of Harbor's end-to-end test.

## User story
As Harbor's test, I want one change per vessel, so that a convoy has something to carry.

## Acceptance criteria
\`\`\`gherkin
Scenario: [S1] The change is on main
  Given the convoy sailed
  Then the change is on main
\`\`\`

## Testable units
| Unit | Test type | File |
|---|---|---|
| none | none | none |

## Definition of done
The convoy sails.
STORY
done
# Once a story is on the trunk Keelokit's doctor wants an active test whose title cites each scenario (TRACE-1).
cat >"$seed/apps/web/src/harbor-demo.test.ts" <<'TS'
import { expect, it } from 'vitest';

it('DEMO-001.S1 The change is on main', () => {
  expect(1).toBe(1);
});

it('DEMO-002.S1 The change is on main', () => {
  expect(2).toBe(2);
});

it('DEMO-003.S1 The change is on main', () => {
  expect(3).toBe(3);
});
TS
# Committed before `pnpm install`, whose `prepare` turns the hooks on, as Keelokit's test-template.sh does:
# the template's ci.yml carries a `continue-on-error` its own pre-commit guard (QA-4) would stop.
git -C "$seed" add -A
git -C "$seed" commit -qm "Demo, generated by Keelokit $tag, under Harbor"
(cd "$seed" && pnpm install --silent && { pnpm -r --if-present --workspace-concurrency=1 e2e:install >/dev/null 2>&1 || true; })
# The seed only builds the remote; the clones below turn the hooks on. From 0.16.0 Keelokit's pre-push refuses a
# push with no origin/main to verify against, which the remote's first push is.
git -C "$seed" config --unset core.hooksPath || true
git -C "$seed" add -A
git -C "$seed" diff --cached --quiet || git -C "$seed" commit -qm "pnpm install" -m "No-story: deps"
# Attribution is required from here on ([ledger] since, as Keelokit's project-new records it): every later commit
# carries a trailer, and an unattributed one is an error for check and attribution.
printf '\n[ledger]\nsince = "%s"\n' "$(git -C "$seed" rev-parse HEAD)" >>"$seed/.keelokit/state.toml"
git -C "$seed" commit -qam "Attribution required from here on" -m "No-story: harness"
git init -q --bare -b main "$work/remote.git"
git -C "$seed" remote add origin "$work/remote.git"
git -C "$seed" push -q origin main

clone() { # clone NAME HOST: one machine
  local dir=$work/$1
  git clone -q "$work/remote.git" "$dir"
  printf '[harbor]\naccount = "acct1"\nhost = "%s"\n' "$2" >"$dir/.keelokit/local.toml"
  git -C "$dir" config core.hooksPath .githooks
  (cd "$dir" && pnpm install --silent --frozen-lockfile)
  echo "$dir"
}
a=$(clone a mbp | tail -1)
b=$(clone b linux | tail -1)

step "The logbook, the account, a skipper who holds the watch"
cd "$a"
H s1 init
H s1 account set acct1 --max-sessions 4
H s1 worker register --role skipper --model sonnet
H s1 harbormaster takeover

vessel() { # vessel BRANCH FILE CONTENT STORY: a story built and verified the way build-story does it
  git -C "$a" checkout -q -B "$1" origin/main
  mkdir -p "$(dirname "$a/$2")"
  printf '%s' "$3" >"$a/$2"
  (cd "$a" && pnpm exec prettier --write "$2" >/dev/null)
  git -C "$a" add -A
  git -C "$a" commit -qm "feat: $1" -m "Harbor's test vessel for $4.

ux-gate: n/a — a test vessel with no screen (Keelokit 0.16.0's UX-3)" -m "Story: $4"
  (cd "$a" && pnpm verify) >"$work/verify-$4.log" 2>&1 || { tail -40 "$work/verify-$4.log"; fail "verify of $4 is red"; }
  git -C "$a" push -q -u origin "$1"
  local sha; sha=$(git -C "$a" rev-parse HEAD)
  [ "$(runs_of "$a" "$sha")" = 1 ] || fail "$4 was verified $(runs_of "$a" "$sha") times; the push should reuse the seal"
  out=$(H s1 seal)
  echo "$out"
  grep -q "already passed Keelokit's verify" <<<"$out" || fail "the seal of $4 ran the verify again instead of reusing it"
  grep -q "pre-push accepts it" <<<"$out" || fail "the seal of $4 has no level"
}

step "Two vessels: a code change and a docs change"
vessel claude/demo-1 apps/web/src/harbor-demo.ts 'export const harborDemo = 1;
' DEMO-001
vessel claude/demo-2 docs/harbor-demo.md '# Harbor demo

A docs-only vessel.
' DEMO-002
v1=$(git -C "$a" rev-parse claude/demo-1)

step "Another machine accepts the vessel's seal without running the verify"
git -C "$b" fetch -q origin claude/demo-1 harbor/log
git -C "$b" checkout -q -B claude/demo-1 origin/claude/demo-1
out=$(cd "$b" && timeout 300 pnpm verify --use-seal 2>&1) || { echo "$out" | tail -20; fail "the shared seal was not accepted on the other clone"; }
echo "$out" | grep "shared seal" || { echo "$out" | tail -20; fail "the other clone ran the verify instead of using the shared seal"; }

step "Taking a story is a lock in the logbook (HRB-2)"
H va worker register --role vessel --model sonnet
(cd "$b" && H vb worker register --role vessel --model sonnet)
H va story take DEMO-001
out=$(cd "$b" && H vb story take DEMO-001 2>&1) && fail "a second machine took DEMO-001 while va held it: $out"
echo "$out"
grep -q "STORY_TAKEN: DEMO-001 is held by acct1/mbp/va" <<<"$out" || fail "the refusal doesn't name the holder: $out"
lk013=$(cd "$a" && timeout 120 python3 .keelokit/bin/ledger.py attribution origin/main..origin/main --json >/dev/null 2>&1 \
  && echo yes || true)
echo "Keelokit's LEDGER-013 (ledger.py attribution answers): ${lk013:-no}"
[ "$tag" != main ] || [ -n "$lk013" ] || fail "Keelokit main has no ledger.py attribution"
if [ -n "$lk013" ]; then  # a vessel prompt's first line, from the second session: Keelokit's take calls Harbor's
  (cd "$b" && H vb check >/dev/null)  # SessionStart records git config --local harbor.py, which Keelokit's take runs
  out=$(cd "$b" && env -u HARBOR_SESSION -u CLAUDE_SESSION_ID CLAUDE_CODE_SESSION_ID=vb \
    python3 .keelokit/bin/ledger.py take DEMO-001 2>&1) && fail "ledger.py take DEMO-001 from vb took it: $out"
  echo "$out"
  grep -q "STORY_TAKEN: DEMO-001 is held by acct1/mbp/va" <<<"$out" || fail "ledger.py take didn't relay STORY_TAKEN: $out"
  [ -z "$(git -C "$b" config --get keelokit.story || true)" ] || fail "a refused take set keelokit.story"
  out=$(cd "$b" && env -u HARBOR_SESSION -u CLAUDE_SESSION_ID CLAUDE_CODE_SESSION_ID=vb \
    python3 .keelokit/bin/ledger.py take DEMO-002 2>&1) || fail "ledger.py take DEMO-002 from vb: $out"
  echo "$out"
  git -C "$a" fetch -q origin harbor/log
  git -C "$a" show origin/harbor/log:harbor/workers/acct1/linux/vb.toml | grep -q '^story = "DEMO-002"' \
    || fail "the session Keelokit handed over (CLAUDE_CODE_SESSION_ID as HARBOR_SESSION) is not the worker holding DEMO-002"
  echo "the worker acct1/linux/vb holds DEMO-002: Keelokit's HARBOR_SESSION is what Harbor read"
  out=$(cd "$b" && env -u HARBOR_SESSION -u CLAUDE_SESSION_ID CLAUDE_CODE_SESSION_ID=vb \
    python3 .keelokit/bin/ledger.py take --clear 2>&1) || fail "ledger.py take --clear from vb: $out"
  echo "$out"
fi
(cd "$b" && H vb worker end)
H va worker end

step "The convoy: new, add, assemble, ok, one verify, sail"
H s1 convoy new --title "Harbor on Keelokit $tag" --expect DEMO-001 DEMO-002
ledger=$(cd "$a" && timeout 120 python3 .keelokit/bin/ledger.py --json 2>/dev/null \
  | python3 -c 'import json, sys; d = json.load(sys.stdin); print("yes" if type(d.get("schema")) is int and d["schema"] == 1 else "")' \
  2>/dev/null || true)
echo "Keelokit's ledger, schema 1: ${ledger:-no}"
if [ -n "$lk013" ]; then  # a real unattributed commit (no hooks: Keelokit's commit-msg would refuse it)
  git -C "$a" checkout -q -B claude/demo-x origin/main
  printf 'export const unattributed = 1;\n' >"$a/apps/web/src/unattributed.ts"
  git -C "$a" add -A
  git -C "$a" -c core.hooksPath=/dev/null commit -qm "feat: nobody's" -m "ux-gate: n/a — a test vessel with no screen"
  x=$(git -C "$a" rev-parse HEAD)
  git -C "$a" -c core.hooksPath=/dev/null push -q origin claude/demo-x
  H s1 seal | tail -1  # green: Keelokit's verify doesn't ask the ledger; convoy add asks attribution after the seal
  out=$(H s1 convoy add 1 claude/demo-x 2>&1) && fail "convoy add took an unattributed vessel: $out"
  echo "$out"
  grep -q "NO_STORY: ${x:0:9}" <<<"$out" || fail "not NO_STORY for ${x:0:9} from ledger.py attribution: $out"
  git -C "$a" checkout -q claude/demo-1
fi
for v in "claude/demo-1 light DEMO-001" "claude/demo-2 trivial DEMO-002"; do
  set -- $v
  out=$(H s1 convoy add 1 "$1" --tier "$2")
  echo "$out"
  story=$(git -C "$a" show origin/harbor/log:harbor/convoys/1.toml | python3 -c '
import sys, tomllib
print(next(v.get("story", "") for v in tomllib.loads(sys.stdin.read())["vessels"] if v["branch"] == sys.argv[1]))' "$1")
  [ "$story" = "$3" ] || fail "vessel $1 got story '$story', not $3"
  if [ -n "$ledger" ] && ! grep -q "ledger: attribution not available" <<<"$out"; then echo "  its story came from ledger.py attribution"; fi
  [ -z "$lk013" ] || ! grep -q "ledger: attribution not available" <<<"$out" || fail "with LEDGER-013 the attribution didn't answer: $out"
  [ -n "$ledger" ] || ! grep -q "ledger" <<<"$out" || fail "without the ledger, convoy add spoke of it (0.5 says nothing)"
done
out=$(H s1 convoy assemble 1)
echo "$out"
grep -q "recorded as the convoy's seal" <<<"$out" || fail "the pre-push verify of convoy/1 was not recorded as its seal"
merges=$(git -C "$a" log --first-parent --merges --format=%H origin/main..origin/convoy/1)
for m in $merges; do
  subject=$(git -C "$a" log -1 --format=%s "$m")
  convoy=$(git -C "$a" log -1 --format='%(trailers:key=Convoy,valueonly)' "$m" | sed '/^$/d')
  if [ -n "$ledger" ]; then
    [ "$convoy" = 1 ] || fail "the merge '$subject' carries Convoy: '${convoy}', not exactly one Convoy: 1"
    [ "$(git -C "$a" log -1 --format=%B "$m" | sed '/^$/d' | tail -1)" = "Convoy: 1" ] || fail "'$subject' doesn't end with Convoy: 1"
  else
    [ -z "$convoy" ] || fail "without the ledger the merge '$subject' carries a Convoy: trailer"
  fi
done
if [ -n "$ledger" ]; then
  [ "$(wc -w <<<"$merges")" = 2 ] || fail "with the ledger, each of the two vessels has its own merge (found: $merges)"
  echo "each vessel's merge ends with Convoy: 1"
fi
out=$(H s1 convoy sail 1 --ok --level changed --reason "apps/web and docs only")
echo "$out"
if [ -n "$lk013" ]; then
  grep -q "judged by main's rules (check --rules-ref" <<<"$out" || fail "the ok didn't pass --rules-ref to check: $out"
elif [ -n "$ledger" ]; then
  grep -q "no check --rules-ref" <<<"$out" || fail "the ok didn't say main's ledger has no --rules-ref: $out"
fi
if [ -n "$ledger" ]; then  # HRB-3: the ok asked Keelokit's real ledger (check --json) and found nothing against the vessels
  git -C "$a" show origin/harbor/log:harbor/convoys/1.toml | grep -q '^ledger = "checked"' || fail "the ok didn't ask the ledger"
  echo "the ok asked ledger.py --json and check --json"
fi
H s1 convoy verify 1 >"$work/convoy-verify.log" 2>&1 || { tail -60 "$work/convoy-verify.log"; fail "the convoy verify is red"; }
tail -3 "$work/convoy-verify.log"
grep -q "nothing to run" "$work/convoy-verify.log" || fail "the convoy verify ran again what assemble's push had verified"
H s1 convoy sail 1 2>&1 | tee "$work/sail.log"
head=$(git -C "$a" rev-parse convoy/1)
[ "$(git -C "$work/remote.git" rev-parse main)" = "$head" ] || fail "main is not at the convoy's head"
git -C "$work/remote.git" merge-base --is-ancestor "$v1" main || fail "vessel DEMO-001 is not on main"
for m in $merges; do
  git -C "$work/remote.git" merge-base --is-ancestor "$m" main || fail "the convoy's merge ${m:0:9} is not on main"
done
seal_of "$a" "$head" | grep -q '^level = "changed"' || fail "the convoy's seal has no level"

step "A story on the trunk can't be taken (HRB-2)"
git -C "$a" fetch -q origin main
H vc worker register --role vessel --model sonnet
if [ -n "$ledger" ]; then
  if [ -n "$lk013" ]; then  # Keelokit's show --json, the answer Harbor asks first
    state=$(cd "$a" && python3 .keelokit/bin/ledger.py show DEMO-001 --json \
      | python3 -c 'import json, sys; d = json.load(sys.stdin); print(d.get("schema"), d.get("state"))')
    [ "$state" = "1 on-trunk" ] || fail "ledger.py show DEMO-001 --json says '$state', not schema 1 on-trunk"
    echo "ledger.py show DEMO-001 --json: on-trunk"
  fi
  out=$(H vc story take DEMO-001 2>&1) && fail "DEMO-001 is on main and was taken: $out"
  echo "$out"
  grep -q "STORY_ON_TRUNK: DEMO-001 is on-trunk" <<<"$out" || fail "not STORY_ON_TRUNK from the ledger: $out"
  ! grep -q "harbor: ledger:" <<<"$out" || fail "the ledger couldn't say: $out"
else
  H vc story take DEMO-001
fi
H vc worker end

if [ -n "$ledger" ]; then
  step "A convoy that adds its own correction row for an unattributed commit is refused by the ok"
  vessel claude/demo-3 apps/web/src/harbor-demo-3.ts 'export const harborDemo3 = 3;
' DEMO-003
  H s1 convoy new --title "A correction of its own" --expect DEMO-003
  H s1 convoy add 2 claude/demo-3 --tier light
  H s1 convoy assemble 2 >"$work/assemble-2.log" 2>&1 || { tail -40 "$work/assemble-2.log"; fail "assemble of convoy 2"; }
  git -C "$a" fetch -q origin convoy/2
  git -C "$a" checkout -q -B convoy/2 origin/convoy/2
  printf 'export const integratorFix = 1;\n' >"$a/apps/web/src/integrator-fix.ts"
  git -C "$a" add -A
  git -C "$a" -c core.hooksPath=/dev/null commit -qm "fix: the integrator's, no trailer" \
    -m "ux-gate: n/a — a test fix with no screen"
  fix=$(git -C "$a" rev-parse HEAD)
  cat >>"$a/backlog/ledger-corrections.toml" <<ROW

[[row]]
story = "DEMO-003"
commit = "$fix"
kind = "late"
evidence = "the convoy says so"
approver = "the convoy"
date = "2026-01-01"
ROW
  git -C "$a" add -A
  git -C "$a" -c core.hooksPath=/dev/null commit -qm "chore: a correction of the convoy's own" -m "No-story: harness"
  git -C "$a" -c core.hooksPath=/dev/null push -q origin convoy/2
  out=$(H s1 convoy assemble 2 2>&1) || { echo "$out"; fail "assemble of convoy 2 after the fix"; }
  out=$(H s1 convoy sail 2 --ok --level changed --reason "apps/web only" 2>&1) && fail "the ok passed a convoy with its own correction: $out"
  echo "$out"
  grep -q "LEDGER_DIFF" <<<"$out" || fail "not LEDGER_DIFF: $out"
  grep -q "UNATTRIBUTED: ${fix:0:9}" <<<"$out" || fail "the integrator's commit ${fix:0:9} is not named UNATTRIBUTED: $out"
  if [ -n "$lk013" ]; then
    landed=${out#*as landed, by main\'s ledger: }
    [ "$landed" != "$out" ] && grep -q "UNATTRIBUTED" <<<"$landed" \
      || fail "main's ledger on the convoy as landed (--rules-ref) didn't name the commit: $out"
    echo "main's ledger as landed, with main's corrections (--rules-ref), names ${fix:0:9} UNATTRIBUTED"
  fi
  H s1 convoy abort 2 --reason "the test's refusal"
  git -C "$a" checkout -q claude/demo-1
fi

step "A logbook write from unverified work runs no verify"
git -C "$a" checkout -q -b scratch
printf 'export const notVerified = 1;\n' >"$a/apps/web/src/not-verified.ts"
git -C "$a" add -A && git -C "$a" commit -qm "work in progress, never verified" -m "No-story: harness"
before=$(history_lines "$a")
out=$(H s1 harbormaster control)
echo "$out"
[ "$(history_lines "$a")" = "$before" ] || fail "a logbook write ran a verify"
if [ -n "$ledger" ]; then  # HRB-3: the round read Keelokit's real check --json
  ! grep -q "ledger: .*not available" <<<"$out" || fail "the round could not read the real ledger: $out"
else
  [ "$(grep -c "ledger: not available" <<<"$out")" = 1 ] || fail "without the ledger the round should say so once"
fi
outside=$(git -C "$a" ls-tree -r --name-only origin/harbor/log | grep -v '^harbor/' || true)
[ -z "$outside" ] || fail "logbook files outside harbor/: $outside"

step "The logbook"
git -C "$a" show origin/harbor/log:harbor/LOGBOOK.md | sed -n '1,40p'
printf '\n\033[32m✔ Harbor on Keelokit %s: each vessel verified once, seals shared across clones, logbook writes free, one convoy on main at %s\033[0m\n' \
  "$tag" "${head:0:9}"
